import{_ as a,o as n,c as t,ae as s}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse('{"title":"Confluence: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/confluence.md","filePath":"adrs/1917971986/references/confluence.md"}'),o={name:"adrs/1917971986/references/confluence.md"};function i(r,e,c,l,d,h){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="confluence-hierarchy-audiences-and-access" tabindex="-1">Confluence: hierarchy, audiences, and access <a class="header-anchor" href="#confluence-hierarchy-audiences-and-access" aria-label="Permalink to &quot;Confluence: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>An Atlassian organization sits above everything and is managed from admin.atlassian.com. An organization is created automatically, together with a site, the moment anyone signs up for an Atlassian cloud product, so the layer exists from the first signup rather than being something a customer opts into later (<a href="https://support.atlassian.com/organization-administration/docs/get-started-with-an-atlassian-organization/" target="_blank" rel="noreferrer">Create an Atlassian organization</a>). An organization can contain one or more sites, and each site can run one instance of each Atlassian product, including Confluence (<a href="https://support.atlassian.com/organization-administration/docs/what-is-an-atlassian-organization/" target="_blank" rel="noreferrer">What is an Atlassian organization?</a>).</p><p>Inside a Confluence site, content lives in spaces. A space holds pages, and pages can have child pages, forming a tree. Within a space, folders are an additional container that sits in that same content tree, alongside pages; a folder can be nested under another folder or under a page, and Confluence does not document a maximum nesting depth (<a href="https://support.atlassian.com/confluence-cloud/docs/use-folders-to-organize-your-work/" target="_blank" rel="noreferrer">Use folders to organize your work</a>). Folders are simple containers with no page content of their own, unlike a parent page, which carries its own text in addition to grouping its children.</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>The organization is the governance layer: it manages identity through managed accounts tied to a verified domain, centralizes billing across every product in the organization, and, with Atlassian Guard Standard, provides audit logs and security reporting across the organization (<a href="https://support.atlassian.com/organization-administration/docs/what-is-an-atlassian-organization/" target="_blank" rel="noreferrer">What is an Atlassian organization?</a>). Work itself, meaning spaces and the pages and folders inside them, lives at the site and space level, not at the organization level.</p><p>Within Confluence, space permissions are the baseline grant of access to a space, covering who can view, create, edit, comment, and administer content in that space, assigned through default or custom roles such as Admin, Manager, Collaborator, and Viewer (<a href="https://support.atlassian.com/confluence-cloud/docs/what-are-space-permissions/" target="_blank" rel="noreferrer">What are space permissions?</a>). Page restrictions then narrow that baseline for an individual page or folder.</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>Confluence does not expose a single named set of audiences the way the ADR&#39;s Public, Organization, Inherited, and Invited-members list does. Instead, visibility is built from three layers that compose:</p><ul><li>Site-level, global settings, including whether anonymous access is permitted at all for the site.</li><li>Space permissions, which a space admin sets for named users, groups, or anonymous visitors.</li><li>Page restrictions, which narrow a specific page or folder to named people or groups.</li></ul><p>A site can allow anyone on the internet, with no Atlassian account, to view a space&#39;s content if a Confluence admin enables anonymous access at the site level and a space admin then turns it on for that space, with view generally recommended over edit, create, or comment (<a href="https://support.atlassian.com/confluence-cloud/docs/make-a-space-public/" target="_blank" rel="noreferrer">Make a space public with anonymous access</a>). New sites enforce site-level control by default, meaning anonymous access must first be allowed site-wide before any individual space can turn it on (<a href="https://support.atlassian.com/confluence-cloud/docs/make-a-space-public/" target="_blank" rel="noreferrer">Make a space public with anonymous access</a>).</p><p>Guests are a separate, named audience: external users invited by an organization or site admin, who by default can view pages, add pages, comment, and attach files, but who can never be granted space administration, export, or restriction permissions (<a href="https://support.atlassian.com/confluence-cloud/docs/what-can-guests-see-and-do-on-confluence" target="_blank" rel="noreferrer">What can guests see and do in Confluence?</a>). A guest can only be assigned to one space at a time, so a guest&#39;s reach is deliberately narrower than the ADR&#39;s &quot;invited members&quot; audience, which can span a workspace or folder (<a href="https://support.atlassian.com/confluence-cloud/docs/what-can-guests-see-and-do-on-confluence" target="_blank" rel="noreferrer">What can guests see and do in Confluence?</a>).</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>Page restrictions let a page or folder narrow access below what the space permissions or a parent page would otherwise allow, and the mechanism differs by capability:</p><ul><li>View restrictions cascade automatically: &quot;If someone can&#39;t view a parent content item or folder, they won&#39;t be able to view any child content items under it&quot; (<a href="https://support.atlassian.com/confluence-cloud/docs/add-or-remove-page-restrictions/" target="_blank" rel="noreferrer">Change who can find content and what they can do with it</a>). When a page already inherits a view restriction from its parent and then adds its own, a person must satisfy both to see it.</li><li>Edit restrictions do not cascade from a parent page to its children: &quot;Even if someone is restricted from editing a parent item, they won&#39;t automatically be restricted from editing the child content&quot; (<a href="https://support.atlassian.com/confluence-cloud/docs/add-or-remove-page-restrictions/" target="_blank" rel="noreferrer">Change who can find content and what they can do with it</a>). Edit restrictions set at the space level are the exception, since they apply to everything in the space.</li></ul><p>Setting or changing a restriction requires both edit permission on the page and Restrict, or Admin, permission in the space (<a href="https://support.atlassian.com/confluence-cloud/docs/add-or-remove-page-restrictions/" target="_blank" rel="noreferrer">Change who can find content and what they can do with it</a>). A person cannot be given access to one page without also holding access to the space it lives in; page restrictions only ever narrow a space member&#39;s access, they cannot grant access beyond the space.</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>Ceilings run from the site downward, not from the organization downward in a documented way. A Confluence admin can enforce site-level control over anonymous access, which caps what any individual space admin can turn on; while that enforcement is active, anonymous access must be allowed at the site before a space can use it at all (<a href="https://support.atlassian.com/confluence-cloud/docs/make-a-space-public/" target="_blank" rel="noreferrer">Make a space public with anonymous access</a>). Site admins also manage global permissions, including guest space assignment and the handling of public links, from one place in Confluence administration (<a href="https://support.atlassian.com/confluence-cloud/docs/manage-site-level-permissions/" target="_blank" rel="noreferrer">Manage site-level permissions</a>). Whether the organization layer itself can enforce a ceiling that a site admin cannot override is not documented in the pages reviewed.</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>Confluence lets admins decide whether people can even ask for access. Turning off space access requests &quot;prevents users from requesting access to all spaces&quot; in the site, and admins can separately turn off requests for individual pages, blogs, and whiteboards, after which anyone hitting restricted content sees a plain restricted-access message instead of a request button (<a href="https://support.atlassian.com/confluence-cloud/docs/manage-confluence-access-requests/" target="_blank" rel="noreferrer">Manage Confluence access requests</a>). When requests remain on, Confluence routes the request by email to the content&#39;s recent editors or, failing that, to a space admin who can see the page (<a href="https://support.atlassian.com/confluence-cloud/docs/manage-confluence-access-requests/" target="_blank" rel="noreferrer">Manage Confluence access requests</a>).</p><p>Confluence narrows discovery along with access for restricted pages: a restricted page &quot;won&#39;t display for anyone who doesn&#39;t have permission to view it, neither in the content tree nor any macros,&quot; so its title is not surfaced to people who lack access, though someone holding a direct link will see the title in the page itself (<a href="https://support.atlassian.com/confluence-cloud/docs/add-or-remove-page-restrictions/" target="_blank" rel="noreferrer">Change who can find content and what they can do with it</a>). This is the closed end of the ADR&#39;s discovery spectrum: narrowing here also closes discovery, it does not leave existence visible the way a Google Drive limited-access folder does.</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>The organization and its first site are created together at signup, so there is no separate step that introduces the organization later (<a href="https://support.atlassian.com/organization-administration/docs/get-started-with-an-atlassian-organization/" target="_blank" rel="noreferrer">Create an Atlassian organization</a>). Whether a single-site customer is shown the organization admin surface, or can avoid it entirely the way a one-workspace Slack team avoids an Enterprise Grid organization, is not addressed in the pages reviewed.</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>Separately created Atlassian organizations are not merged by an ordinary administrative action. Atlassian describes the operation as organization consolidation, in which all sites, products, and users transfer from a source organization into a destination organization; site URLs and apps are not changed or affected during the transfer, but the process &quot;is not reversible,&quot; and the two organizations cannot later be split apart (<a href="https://support.atlassian.com/atlassian-cloud/kb/atlassian-organization-consolidation-guide/" target="_blank" rel="noreferrer">Atlassian Organization consolidation guide</a>). Consolidation is only available under specific conditions, for example both organizations using centralized user management, and some setups, such as those using Atlassian Guard Premium or Atlassian Collections, are not eligible for self-service consolidation at all (<a href="https://support.atlassian.com/organization-administration/docs/should-i-merge-my-atlassian-organizations" target="_blank" rel="noreferrer">Can I merge my Atlassian organizations?</a>).</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>Confluence&#39;s organization-site-space-page tree maps closely onto the ADR&#39;s organization-workspace-folder-project shape: the organization governs identity and billing exactly as this ADR&#39;s root does, and work, meaning spaces and their content, sits below it rather than at the root, matching the ADR&#39;s rule that work never attaches at the root.</li><li>Confluence folders are the clearest external precedent for this ADR&#39;s optional, freely nestable folder level: a folder is &quot;any node below a workspace&quot; in the ADR&#39;s words, and a Confluence folder is similarly just a deeper position in the same content tree, with no separate permission model of its own.</li><li>Confluence&#39;s view-cascades, edit-does-not pattern is a concrete instance of the ADR&#39;s &quot;any level may widen or narrow&quot; rule, and it shows that narrowing does not have to be uniform across capabilities, which is exactly what the ADR&#39;s &quot;audiences differ per capability&quot; point anticipates. View restrictions are also one of the ADR&#39;s two closed discovery cases, since a restricted page&#39;s existence is hidden rather than left visible for a request, matching the ADR&#39;s Slack private-channel example rather than its Google Drive limited-access example.</li><li>Where Confluence diverges from the ADR is in root-level opt-in ceilings: Confluence&#39;s documented ceiling (site-level enforcement of anonymous access) sits at the site, one level below the ADR&#39;s root, and no reviewed page describes the organization itself enforcing a policy ceiling onto a site the way the ADR expects the root to cap every level below it.</li><li>Confluence does not confirm the ADR&#39;s one-workspace-customer invisibility rule the way Slack&#39;s plan structure does; an organization and site exist together from signup, and no reviewed page states whether a single-site customer can avoid the organization admin surface, so this remains an open gap rather than a confirmed agreement or divergence.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://support.atlassian.com/organization-administration/docs/what-is-an-atlassian-organization/" target="_blank" rel="noreferrer">What is an Atlassian organization?</a></li><li><a href="https://support.atlassian.com/organization-administration/docs/get-started-with-an-atlassian-organization/" target="_blank" rel="noreferrer">Create an Atlassian organization</a></li><li><a href="https://support.atlassian.com/confluence-cloud/docs/use-folders-to-organize-your-work/" target="_blank" rel="noreferrer">Use folders to organize your work</a></li><li><a href="https://support.atlassian.com/confluence-cloud/docs/what-are-space-permissions/" target="_blank" rel="noreferrer">What are space permissions?</a></li><li><a href="https://support.atlassian.com/confluence-cloud/docs/manage-site-level-permissions/" target="_blank" rel="noreferrer">Manage site-level permissions</a></li><li><a href="https://support.atlassian.com/confluence-cloud/docs/add-or-remove-page-restrictions/" target="_blank" rel="noreferrer">Change who can find content and what they can do with it (add or remove page restrictions)</a></li><li><a href="https://support.atlassian.com/confluence-cloud/docs/manage-confluence-access-requests/" target="_blank" rel="noreferrer">Manage Confluence access requests</a></li><li><a href="https://support.atlassian.com/confluence-cloud/docs/make-a-space-public/" target="_blank" rel="noreferrer">Make a space public with anonymous access</a></li><li><a href="https://support.atlassian.com/confluence-cloud/docs/what-can-guests-see-and-do-on-confluence" target="_blank" rel="noreferrer">What can guests see and do in Confluence?</a></li><li><a href="https://support.atlassian.com/confluence-cloud/docs/assign-space-access-to-guests/" target="_blank" rel="noreferrer">Assign space access to guests</a></li><li><a href="https://support.atlassian.com/organization-administration/docs/should-i-merge-my-atlassian-organizations" target="_blank" rel="noreferrer">Can I merge my Atlassian organizations?</a></li><li><a href="https://support.atlassian.com/atlassian-cloud/kb/atlassian-organization-consolidation-guide/" target="_blank" rel="noreferrer">Atlassian Organization consolidation guide</a></li></ul>',30)])])}const g=a(o,[["render",i]]);export{p as __pageData,g as default};
